<script setup lang="ts">
import {onMounted,ref} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import {Plus,Refresh} from '@element-plus/icons-vue'
import {http,errorMessage} from '../lib/http'
import type {Page,Post} from '../lib/types'
import {useAuthStore} from '../stores/auth'
const auth=useAuthStore(),items=ref<Post[]>([]),total=ref(0),page=ref(1),loading=ref(false),error=ref('')
const webUrl=import.meta.env.VITE_WEB_URL||(import.meta.env.DEV?'http://127.0.0.1:5173/':'/')
async function load(){loading.value=true;error.value='';try{const {data}=await http.get<Page<Post>>('/admin/posts',{params:{page:page.value,page_size:20}});items.value=data.items;total.value=data.total}catch(e){error.value=errorMessage(e)}finally{loading.value=false}}
async function remove(id:number,title:string){try{await ElMessageBox.confirm(`确定删除《${title}》？附件文件会保留。`,'删除文章',{type:'warning',confirmButtonText:'删除',cancelButtonText:'取消'});await http.delete(`/admin/posts/${id}`);ElMessage.success('文章已删除');if(items.value.length===1&&page.value>1)page.value--;await load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(errorMessage(e))}}
onMounted(()=>void load())
</script>
<template><section><div class="page-heading"><div><p class="section-kicker">YOUR JOURNAL</p><h1>文章管理</h1><p>已发布的故事，与尚在酝酿的想法。</p></div><div><el-button :icon="Refresh" @click="load">刷新</el-button><el-button v-if="auth.can('posts:write')" type="primary" :icon="Plus" @click="$router.push('/articles/new')">写文章</el-button></div></div><el-alert v-if="error" :title="error" type="error" show-icon :closable="false"/><el-card shadow="never"><el-table v-loading="loading" :data="items" empty-text="还没有文章，点击“写文章”记录第一篇故事"><el-table-column label="文章" min-width="260"><template #default="{row}"><div class="table-post"><b>{{row.title}}</b><small>{{row.summary}}</small></div></template></el-table-column><el-table-column prop="category" label="分类" width="130"/><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="row.status==='published'?'success':'info'" effect="plain">{{row.status==='published'?'已发布':'草稿'}}</el-tag></template></el-table-column><el-table-column prop="views" label="阅读" width="80"/><el-table-column label="更新日期" width="130"><template #default="{row}">{{new Date(row.updatedAt).toLocaleDateString('zh-CN')}}</template></el-table-column><el-table-column label="操作" width="190" fixed="right"><template #default="{row}"><el-button v-if="auth.can('posts:write')" link type="primary" @click="$router.push(`/articles/${row.id}/edit`)">编辑</el-button><a v-if="row.status==='published'" :href="`${webUrl.replace(/\/$/,'')}/posts/${row.id}`" target="_blank" rel="noopener noreferrer" class="table-link">查看</a><el-button v-if="auth.can('posts:delete')" link type="danger" @click="remove(row.id,row.title)">删除</el-button></template></el-table-column></el-table><el-pagination v-if="total>20" v-model:current-page="page" :total="total" :page-size="20" layout="total,prev,pager,next" class="table-pagination" @current-change="load"/></el-card></section></template>
